import { useAuth } from '../context/AuthContext';

// ── Navigation items by role ─────────────────────────────────────────────────
// Each entry: { path, label, icon, roles: [] (empty = all roles) }
const NAV_ITEMS = [
  { path: '/',                   label: 'Dashboard',         icon: '◈',  roles: [] },
  { path: '/employees',          label: 'Employees',         icon: '◉',  roles: ['hr', 'admin', 'hr_head'] },
  { path: '/employee-sections',  label: 'Employee Directory',icon: '⊞',  roles: ['hr', 'admin', 'hr_head'] },
  { path: '/templates',          label: 'Templates',         icon: '⬡',  roles: ['hr', 'admin', 'hr_head'] },
  { path: '/letters',            label: 'Offer Letters',     icon: '◇',  roles: ['hr', 'admin', 'hr_head'] },
  { path: '/appointment-orders', label: 'Appointment Orders',icon: '📄', roles: ['hr', 'admin', 'hr_head'] },
  { path: '/approvals',          label: 'Approvals',         icon: '✓',  roles: ['manager', 'hr_head', 'admin'] },
  { path: '/exit',               label: 'Exit & Relieving',  icon: '○',  roles: ['hr', 'admin', 'hr_head'] },
];

export default function Layout({ children, currentPath }) {
  const { user, logout } = useAuth();

  const visible = NAV_ITEMS.filter(
    item => item.roles.length === 0 || item.roles.includes(user?.role)
  );

  const go = (path) => { window.location.hash = path; };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: 'var(--bg)' }}>

      {/* ── Sidebar ── */}
      <aside style={{
        width: 220, flexShrink: 0,
        background: 'var(--surface)',
        borderRight: '1px solid var(--border)',
        display: 'flex', flexDirection: 'column',
        position: 'sticky', top: 0, height: '100vh',
      }}>
        {/* Logo */}
        <div style={{ padding: '24px 20px 20px', borderBottom: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{
              width: 34, height: 34, borderRadius: 10,
              background: 'var(--accent-dim)', border: '1px solid var(--accent)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 16, color: 'var(--accent)',
            }}>◈</div>
            <div>
              <div style={{ fontFamily: 'var(--display)', fontWeight: 800, fontSize: 14, letterSpacing: '-0.02em' }}>
                HR<span style={{ color: 'var(--accent)' }}>Letters</span>
              </div>
              <div style={{ fontSize: 10, color: 'var(--text-dim)', fontFamily: 'var(--mono)', marginTop: 1 }}>
                {user?.role?.toUpperCase()}
              </div>
            </div>
          </div>
        </div>

        {/* Nav */}
        <nav style={{ flex: 1, overflowY: 'auto', padding: '12px 10px' }}>
          {visible.map(item => {
            const active = currentPath === item.path;
            return (
              <button key={item.path}
                onClick={() => go(item.path)}
                style={{
                  width: '100%', textAlign: 'left',
                  display: 'flex', alignItems: 'center', gap: 10,
                  padding: '9px 12px', borderRadius: 'var(--radius)',
                  marginBottom: 2, border: 'none',
                  background: active ? 'var(--accent-dim)' : 'transparent',
                  color:      active ? 'var(--accent)'    : 'var(--text-muted)',
                  fontWeight: active ? 600                : 400,
                  fontSize: 13, cursor: 'pointer',
                  transition: 'all 0.15s',
                  borderLeft: `3px solid ${active ? 'var(--accent)' : 'transparent'}`,
                }}
                onMouseEnter={e => !active && (e.currentTarget.style.background = 'var(--surface-2)', e.currentTarget.style.color = 'var(--text)')}
                onMouseLeave={e => !active && (e.currentTarget.style.background = 'transparent', e.currentTarget.style.color = 'var(--text-muted)')}
              >
                <span style={{ fontSize: 15, minWidth: 18, textAlign: 'center' }}>{item.icon}</span>
                {item.label}
              </button>
            );
          })}
        </nav>

        {/* User footer */}
        <div style={{ padding: '16px 16px', borderTop: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
            <div style={{
              width: 30, height: 30, borderRadius: '50%',
              background: 'var(--accent-dim)', border: '1px solid var(--accent)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 13, fontWeight: 700, color: 'var(--accent)',
              flexShrink: 0,
            }}>
              {user?.name?.[0]?.toUpperCase()}
            </div>
            <div style={{ overflow: 'hidden' }}>
              <div style={{ fontSize: 12, fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{user?.name}</div>
              <div style={{ fontSize: 10, color: 'var(--text-dim)', fontFamily: 'var(--mono)' }}>{user?.email}</div>
            </div>
          </div>
          <button className="btn btn-secondary btn-sm" style={{ width: '100%', justifyContent: 'center', fontSize: 11 }} onClick={logout}>
            Sign out
          </button>
        </div>
      </aside>

      {/* ── Main content ── */}
      <main style={{ flex: 1, overflow: 'auto' }}>
        <div style={{ padding: '28px 32px', maxWidth: 1280, margin: '0 auto' }}>
          {children}
        </div>
      </main>
    </div>
  );
}
